1. question='What prevailed with the disgrace of "Near East"?'; answer='"Middle East"'; support_paragraph=7
2. question='The World >> located in or next to body of water'; answer='Persian Gulf'; support_paragraph=18
3. question='what region lies immediately to the north of #1 and #2'; answer='Kingdom of Saudi Arabia'; support_paragraph=13
4. question='when was #3 established'; answer='1932'; support_paragraph=19

